SELECT a.fav_id, a.app_id, a.sort_order, a.app_id AS workbenchAppId, wa.app_name FROM bt_user_fav_app a LEFT JOIN bt_workbench_app wa ON wa.workbench_app_id = a.app_id WHERE a.status_cd = '00A' AND wa.status_cd = '00A' AND wa.app_status = 'A' AND a.user_id = #{params.userId} AND a.space_id = #{params.spaceId}
AND exists( SELECT 1 FROM bt_workbench_app_auth au WHERE au.status_cd = '00A' AND au.workbench_app_id = a.app_id AND (au.user_id IN (#{params.userId}, -1)
OR au.org_id IN (#{orgId})
) )
ORDER BY a.sort_order, a.updated_time

